with gaps as (select *, case when event_time - lag(event_time) over (partition by page order by event_time, id) > interval 14 days then 1 else 0 end as is_new_burst from web_events), islands as (select *, sum(is_new_burst) over (partition by page order by event_time, id rows between unbounded preceding and current row) as burst_id from gaps) select s.id, s.session_id, s.page, s.event_time, s.duration_sec, s.is_new_burst, s.burst_id, (select max(x.duration_sec) from web_events x where x.session_id = s.session_id) as max_web_event_duration_sec from islands s order by page desc nulls last;
